// Unicode predicates behind Python's str semantics.
//
// Node's RegExp Unicode property escapes expose the same category data
// CPython consults, so no tables need to be tabulated by hand here.

const NON_PRINTABLE = /^[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]$/u;
const DECIMAL_DIGIT = /^\p{Nd}$/u;

// The set int() strips from around a literal. It is str.isspace() minus
// U+001C..U+001F, which int() rejects even though isspace() accepts them.
const INT_WHITESPACE = /^(?:[\t\n\v\f\r   ]|\p{Zs})$/u;

// str.isprintable(): everything outside the C* and Z* categories, plus the
// space character itself, which is printable despite being Zs.
export function isPrintable(ch) {
  return ch === ' ' || !NON_PRINTABLE.test(ch);
}

export function isIntWhitespace(ch) {
  return INT_WHITESPACE.test(ch);
}

export function isDecimalDigit(ch) {
  return DECIMAL_DIGIT.test(ch);
}

// Every Nd block is ten consecutive code points running 0..9, so a digit's
// value is its distance from the first non-digit below it.
export function decimalDigitValue(ch) {
  const codePoint = ch.codePointAt(0);
  for (let value = 0; value < 10; value += 1) {
    const below = codePoint - value - 1;
    if (below < 0 || !DECIMAL_DIGIT.test(String.fromCodePoint(below))) return value;
  }
  return 0;
}

