// Python's bytes modelled as an immutable sequence of integers in 0..255.
//
// The octets live in a plain Array, which keeps the codec, repr and bencode
// layers free of any typed-sequence machinery.

export class PyBytes {
  constructor(codes = []) {
    this.codes = codes;
  }

  // Reads an ASCII/Latin-1 source string one octet per character. Used for
  // the fixed bencode markers ('i', 'e', ':', digits) and nothing else.
  static fromLatin1(text) {
    const codes = [];
    for (let index = 0; index < text.length; index += 1) {
      codes.push(text.charCodeAt(index));
    }
    return new PyBytes(codes);
  }

  static concat(parts) {
    const codes = [];
    for (const part of parts) {
      for (const code of part.codes) codes.push(code);
    }
    return new PyBytes(codes);
  }

  get length() {
    return this.codes.length;
  }

  slice(start, end) {
    return new PyBytes(this.codes.slice(start, end));
  }

  // Inverse of fromLatin1, for inspecting a decoded region as text.
  toLatin1() {
    let text = '';
    for (const code of this.codes) text += String.fromCharCode(code);
    return text;
  }
}

export function isPyBytes(value) {
  return value instanceof PyBytes;
}

