// The subset of Python's exception hierarchy this program can raise, carrying
// enough detail to reproduce the interpreter's traceback text.

export class PythonError extends Error {
  constructor(typeName, detail) {
    super(`${typeName}: ${detail}`);
    this.typeName = typeName;
    this.detail = detail;
  }

  // The final line of a traceback: "TypeName: detail".
  toPythonLine() {
    return `${this.typeName}: ${this.detail}`;
  }
}

export class ValueError extends PythonError {
  constructor(detail) {
    super('ValueError', detail);
  }
}

export class TypeError_ extends PythonError {
  constructor(detail) {
    super('TypeError', detail);
  }
}

// Rendered as \xHH, \uHHHH or \UHHHHHHHH depending on magnitude — the form
// CPython's codec error messages use for the offending character.
function escapeCodePoint(codePoint) {
  if (codePoint < 0x100) return `\\x${codePoint.toString(16).padStart(2, '0')}`;
  if (codePoint < 0x10000) return `\\u${codePoint.toString(16).padStart(4, '0')}`;
  return `\\U${codePoint.toString(16).padStart(8, '0')}`;
}

export class UnicodeEncodeError extends PythonError {
  constructor(encoding, codePoint, position) {
    super(
      'UnicodeEncodeError',
      `'${encoding}' codec can't encode character '${escapeCodePoint(codePoint)}' ` +
        `in position ${position}: ordinal not in range(128)`,
    );
    this.encoding = encoding;
    this.codePoint = codePoint;
    this.position = position;
  }
}

// Raised by the argument parser instead of terminating the process directly,
// so the entry point owns every exit path.
export class SystemExit extends Error {
  constructor(code) {
    super(`SystemExit: ${code}`);
    this.code = code;
  }
}

