// str.encode(...) for the one codec this program needs.

import { PyBytes } from './bytes.mjs';
import { UnicodeEncodeError } from './errors.mjs';

// The strict ascii codec. Positions are counted in code points, matching
// CPython, so an astral character occupies one position rather than two.
export function encodeAscii(text) {
  const codes = [];
  let position = 0;
  for (const ch of text) {
    const codePoint = ch.codePointAt(0);
    if (codePoint > 0x7f) throw new UnicodeEncodeError('ascii', codePoint, position);
    codes.push(codePoint);
    position += 1;
  }
  return new PyBytes(codes);
}

