// Rendering of an unhandled exception the way the frozen interpreter does.

import { writeStderr, processId } from './sys.mjs';

// The frozen build reports the frame but not its source line, since the .py
// text is not shipped inside the executable.
export function reportUnhandled(error, { fileName, lineNumber, scriptName }) {
  let out = 'Traceback (most recent call last):\n';
  out += `  File "${fileName}", line ${lineNumber}, in <module>\n`;
  out += `${error.toPythonLine()}\n`;
  out += `[PYI-${processId()}:ERROR] Failed to execute script '${scriptName}' ` +
    'due to unhandled exception!\n';
  writeStderr(out);
}

