cd /tmp && cat > nd.mjs <<'EOF'
// Find every maximal run of consecutive \p{Nd} code points.
const re = /^\p{Nd}$/u;
const runs = [];
let start = -1;
for (let cp = 0; cp <= 0x10ffff; cp++) {
  if (cp >= 0xd800 && cp <= 0xdfff) { if (start >= 0) { runs.push([start, cp-1]); start = -1; } continue; }
  const isNd = re.test(String.fromCodePoint(cp));
  if (isNd && start < 0) start = cp;
  else if (!isNd && start >= 0) { runs.push([start, cp - 1]); start = -1; }
}
if (start >= 0) runs.push([start, 0x10ffff]);
const bad = runs.filter(([a, b]) => (b - a + 1) !== 10);
console.log('total Nd runs:', runs.length);
console.log('runs whose length != 10:', bad.length);
for (const [a, b] of bad) console.log('  U+' + a.toString(16) + '..U+' + b.toString(16), 'len', b-a+1);
console.log('unicode version:', process.versions.unicode ?? 'n/a', '| node', process.version);
EOF
node nd.mjs

cd /tmp
node -e '
const cases=[];
// double-struck 1..9 (U+1D7D8 is zero), sans-serif, monospace
for (const [name,zero] of [["bold",0x1D7CE],["double-struck",0x1D7D8],["sans",0x1D7E2],["sans-bold",0x1D7EC],["mono",0x1D7F6]]) {
  for (const d of [1,5,9]) cases.push({name:`${name}-${d}`,argv:["--a","q","--b",String.fromCodePoint(zero+d)]});
}
require("fs").writeFileSync("/tmp/cases-nd.json", JSON.stringify(cases));
'
node /tmp/harness/diff.mjs --file /tmp/cases-nd.json

