A('sq', '--a', "sq'only", '--b', '1');
A('dq', '--a', 'dq"only', '--b', '1');
A('both', '--a', 'it\'s a "t"', '--b', '1');
A('neither', '--a', 'plain', '--b', '1');
A('many sq', '--a', "'''", '--b', '1');
A('many dq', '--a', '"""', '--b', '1');
A('sq dq mix', '--a', '\'"\'"', '--b', '1');
