// Builds the regression corpus for the differential harness.
//   node /tmp/harness/gen-regression.mjs > /tmp/cases-regression.json

const cases = [];
const A = (name, ...argv) => cases.push({ name, argv });

// The four samples recorded in the source file
A('sample1', '--a', 'utf8', '--b', '65535');
A('sample2', '--a', 'decode', '--b', '-7');
A('sample3', '--a', 'dict', '--b', '1000');
A('sample4', '--a', 'dict', '--b', '-1000');

// argparse: required, unknown, help routes
A('no args');
A('missing b', '--a', 'x');
A('missing a', '--b', '5');
A('unknown', '--a', 'x', '--b', '1', '--c', '2');
A('extra', '--a', 'q', '--b', '5', 'extra');
A('help', '--help');
A('-h', '-h');
A('--h', '--h');
A('--he', '--he');
A('--hel', '--hel');
A('-ha', '-ha');
A('--help=x', '--help=x');
A('-h=x', '-h=x');
A('-xh', '-xh');
A('h first', '-h', '--a', 'q');
A('h last', '--a', 'q', '--b', '5', '-h');
A('badint then h', '--b', 'abc', '-h');
A('h then badint', '-h', '--b', 'abc');
A('unk then h', '--a', 'q', '--b', '5', '--unknown', '-h');
A('unk first', '--unknown', '--a', 'q', '--b', '5');
A('-z', '--a', 'q', '--b', '5', '-z');

// "--" in every position
A('sep val', '--a', 'q', '--b', '--', '5');
A('sep trail', '--a', 'q', '--b', '5', '--');
A('sep first', '--', '--a', 'q', '--b', '5');
A('sep mid', '--a', 'q', '--', '--b', '5');
A('sep sep', '--a', 'q', '--b', '5', '--', '--');
A('sep extra', '--a', 'q', '--b', '5', '--', 'extra');

// "=" forms, duplicates, option-shaped values
A('eq', '--a=eq', '--b=7');
A('eq empty a', '--a=', '--b', '5');
A('eq eq', '--a==x', '--b', '5');
A('dup a', '--a', 'q', '--b', '3', '--a', 'z');
A('dup b eq', '--a', 'q', '--b=5', '--b=6');
A('a eats b', '--a', '--b');
A('neg val', '--a', '-5', '--b', '5');
A('dash val', '--a', '-', '--b', '5');
A('opt as val', '--a', '-x', '--b', '5');
A('negfloat', '--a', '-5.5', '--b', '5');
A('negdot', '--a', '-.5', '--b', '5');
A('neg5x', '--a', '-5x', '--b', '5');
A('empty tok', '--a', '', '--b', '5');
A('reorder', '--b', '3', '--a', '4');

// int() grammar
const INT_LITERALS = [
  '+5', '-0', '0', '00012', '-000', '1_000', '1_0_0', '٣_٤', '1__0', '_10',
  '10_', '+_5', '-_5', '- 5', '+ 5', '0x10', '0b1', '0o7', '1e3', '5.0', '5j', 'inf',
  'nan', '', '  -12 ', '1 2', '++5', '--5', '+-5', '-', '+', '5-', '5+',
];
for (const literal of INT_LITERALS) A(`int[${literal}]`, '--a', 'q', '--b', literal);

// magnitudes straddling every machine-word boundary
for (const exponent of [31, 32, 52, 53, 63, 64, 127, 128, 1024]) {
  const magnitude = 2n ** BigInt(exponent);
  A(`2^${exponent}`, '--a', 'q', '--b', magnitude.toString());
  A(`-2^${exponent}`, '--a', 'q', '--b', (-magnitude).toString());
}
A('300 digits', '--a', 'q', '--b', '9'.repeat(300));
A('1000 digits', '--a', 'q', '--b', `-${'7'.repeat(1000)}`);

// the whitespace int() strips, and the look-alikes it does not
const BLANKS = {
  tab: '	', nl: '
', vt: '', ff: ' ', cr: '', sp: ' ',
  fs: '', gs: '', rs: '', us: '', nel: '', nbsp: ' ',
  mongolian: '᠎', ogham: ' ', enquad: ' ', hairsp: ' ',
  zwsp: '​', ls: ' ', ps: ' ', nnbsp: ' ', mmsp: ' ',
  ideosp: '　', bom: '﻿',
};
for (const [name, ch] of Object.entries(BLANKS)) {
  A(`ws-${name}`, '--a', 'q', '--b', `${ch}5${ch}`);
  A(`ws-mid-${name}`, '--a', 'q', '--b', `1${ch}2`);
}

// numeric-looking characters outside Nd must be rejected
for (const ch of ['²', '½', 'Ⅰ', '〇', '一', '⁰', '⓪']) {
  A(`nonNd-${ch.codePointAt(0).toString(16)}`, '--a', 'q', '--b', ch);
}

// ascii codec: which character is reported, and at which code-point position
A('pos0', '--a', 'ábc', '--b', '1');
A('pos1', '--a', 'héllo', '--b', '1');
A('bmp', '--a', 'aΩb', '--b', '1');
A('astral', '--a', 'x\u{1F600}y', '--b', '1');
A('astral pos', '--a', '\u{1F600}\u{1F600}é', '--b', '1');
A('0x7f ok', '--a', '', '--b', '1');
A('0x80', '--a', '', '--b', '1');
A('0xff', '--a', 'ÿ', '--b', '1');
A('0x100', '--a', 'Ā', '--b', '1');
A('0xffff', '--a', '￿', '--b', '1');
A('max cp', '--a', '\u{10FFFF}', '--b', '1');
A('multi bad', '--a', 'aébøc', '--b', '1');
A('late bad', '--a', `${'x'.repeat(500)}é`, '--b', '1');

// repr: every ASCII byte alone and embedded
for (let code = 1; code < 128; code += 1) {
  const ch = String.fromCharCode(code);
  A(`byte-${code}`, '--a', ch, '--b', '1');
  A(`byte-emb-${code}`, '--a', `A${ch}Z`, '--b', '1');
}

// repr quote selection and backslash runs
A('sq', '--a', "sq'only", '--b', '1');
A('dq', '--a', 'dq"only', '--b', '1');
A('both', '--a', 'it\'s a "t"', '--b', '1');
A('neither', '--a', 'plain', '--b', '1');
A('many sq', '--a', "'''", '--b', '1');
A('many dq', '--a', '"""', '--b', '1');
A('sq dq mix', '--a', '\'"\'"', '--b', '1');
for (let n = 1; n <= 5; n += 1) A(`bs${n}`, '--a', '\\'.repeat(n), '--b', '1');
A('bs before sq', '--a', "\\'", '--b', '1');
A('bs before dq', '--a', '\\"', '--b', '1');
A('bs t', '--a', '\\t', '--b', '1');

// values that are themselves valid bencode must round-trip, not be re-parsed
for (const s of ['i5e', 'l4:teste', '3:abc', 'd1:ai1ee', 'le', 'de', 'i-1e', '0:', 'ee']) {
  A(`bencodey[${s}]`, '--a', s, '--b', '1');
}

// lengths that change the decimal length-prefix width
for (const n of [0, 1, 9, 10, 99, 100, 999, 1000, 4095]) {
  A(`len${n}`, '--a', 'x'.repeat(n), '--b', '1');
}

// mnemonic escapes versus \xHH
A('tabnl', '--a', 'ab\tc\nd', '--b', '1');
A('cr', '--a', '\r', '--b', '1');
A('vt ff bel', '--a', ' ', '--b', '1');
A('backspace', '--a', '\b', '--b', '1');
A('esc seq', '--a', '[0m', '--b', '1');
A('del', '--a', '', '--b', '1');

process.stdout.write(JSON.stringify(cases));
process.stderr.write(`regression cases: ${cases.length}\n`);

